import { describe, expect, it } from 'vitest';
import { Add, Float, I, Integral, Mul, Pow, Sym, add, fn, isAlgebraic, isUnsolved, mul, pow, rational, sqrtDepth, sqrtdenest, symbols } from '../../src';
import { sympyStr } from '../sympy-str';

describe("doctests of sympy.simplify.sqrtdenest", () => {
  it("sqrtdenest(z)", () => {
    expect(sympyStr(sqrtdenest(add(pow(add(1, pow(3, rational(1, 2))), rational(1, 2)), pow(add(3, mul(3, pow(3, rational(1, 2)))), rational(1, 2)), mul(-1, pow(add(10, mul(6, pow(3, rational(1, 2)))), rational(1, 2))))))).toBe('0');
  });
  it("sqrtdenest(sqrt((w**2).expand()))", () => {
    expect(sympyStr(sqrtdenest(pow(add(4, pow(add(1, pow(3, rational(1, 2))), rational(1, 2)), mul(2, pow(2, rational(1, 2))), mul(2, pow(add(1, pow(add(1, pow(3, rational(1, 2))), rational(1, 2))), rational(1, 2))), mul(2, pow(2, rational(1, 2)), pow(add(1, pow(add(1, pow(3, rational(1, 2))), rational(1, 2))), rational(1, 2)))), rational(1, 2))))).toBe('1 + sqrt(2) + sqrt(1 + sqrt(1 + sqrt(3)))');
  });
  it("sqrtdenest(sqrt((w**2).expand())) (2)", () => {
    const x = new Sym('x');
    expect(sympyStr(sqrtdenest(pow(add(4, pow(add(1, pow(add(3, x), rational(1, 2))), rational(1, 2)), mul(2, pow(2, rational(1, 2))), mul(2, pow(add(1, pow(add(1, pow(add(3, x), rational(1, 2))), rational(1, 2))), rational(1, 2))), mul(2, pow(2, rational(1, 2)), pow(add(1, pow(add(1, pow(add(3, x), rational(1, 2))), rational(1, 2))), rational(1, 2)))), rational(1, 2))))).toBe('sqrt((sqrt(sqrt(sqrt(x + 3) + 1) + 1) + 1 + sqrt(2))**2)');
  });
  it("sqrtdenest(sqrt(5 + 2 * sqrt(6)))", () => {
    expect(sympyStr(sqrtdenest(pow(add(5, mul(2, pow(6, rational(1, 2)))), rational(1, 2))))).toBe('sqrt(2) + sqrt(3)');
  });
  it("is_algebraic(sqrt(2)*(3/(sqrt(7) + sqrt(5)*sqrt(2))))", () => {
    expect(sympyStr(isAlgebraic(mul(3, pow(2, rational(1, 2)), pow(add(pow(7, rational(1, 2)), pow(10, rational(1, 2))), -1))))).toBe('True');
  });
  it("is_algebraic(sqrt(2)*(3/(sqrt(7) + sqrt(5)*cos(2))))", () => {
    expect(sympyStr(isUnsolved(false))).toBe('False');
  });
  // the arguments do not type-check against the public API
  //   sqrt_biquadratic_denest(z, a, b, r, d2)
  //   => sqrt(2) + sqrt(sqrt(2) + 2) + 2
  it.todo("sqrt_biquadratic_denest(z, a, b, r, d2)");
  it("sqrt_depth(1 + sqrt(2)*(1 + sqrt(3)))", () => {
    expect(sympyStr(sqrtDepth(add(1, mul(pow(2, rational(1, 2)), add(1, pow(3, rational(1, 2)))))))).toBe('1');
  });
  it("sqrt_depth(1 + sqrt(2)*sqrt(1 + sqrt(3)))", () => {
    expect(sympyStr(sqrtDepth(add(1, mul(pow(2, rational(1, 2)), pow(add(1, pow(3, rational(1, 2))), rational(1, 2))))))).toBe('2');
  });
});

